import React from 'react';

import Sunglasses from '@pohodnik/icons/svg/RealWorld/Sunglasses';

import { round } from '@helpers/mathHelper';
import PohAva from '@ui-kit/Ava';
import PohButton from '@ui-kit/Button';
import PohDropdown from '@ui-kit/Dropdown';
import IconsEnum from '@ui-kit/Icon/IconsEnum';

import { IHikingEquip } from '../../../@types/equip.types';
import EquipOptionsWidget from '../../HikingEquip/components/EquipOptionsWidget';
import { previewEquipModal } from '../../HikingEquip/previewEquip/previewEduipModal';

interface ICommonEquipItemProps {
  data: IHikingEquip;
  readonly: boolean;
  onConfirm: () => void;
  onSetUser: () => void;
  onDelete?: () => void;
  onChange?: () => void;
}

const CommonEquipItem: React.FC<ICommonEquipItemProps> = ({
  data,
  onConfirm,
  onSetUser,
  readonly = false,
  onDelete,
  onChange,
}) => {
  const menuItems = [];

  const isConfirmed = data.isConfirm;

  isConfirmed &&
    menuItems.push(
      <button
        key="cancel-edit-equip"
        className="dropdown-item"
        onClick={() => onConfirm()}
        type="button"
      >
        Отменить утверждение
      </button>,
    );
  !isConfirmed &&
    menuItems.push(
      <button
        key="confirm-edit-equip"
        className="dropdown-item"
        onClick={() => onConfirm()}
        type="button"
      >
        Утвердить
      </button>,
    );
  !isConfirmed &&
    menuItems.push(
      <button
        key="user-edit-equip"
        className="dropdown-item"
        onClick={onSetUser}
        type="button"
      >{`${data.fromUser ? 'Перен' : 'Н'}азначить`}</button>,
    );
  !data.id_equip && menuItems.push(<div key="div" className="dropdown-divider" />);
  !data.id_equip &&
    menuItems.push(
      <button key="edit-equip" className="dropdown-item" onClick={onChange} type="button">
        Изменить
      </button>,
    );
  !data.id_equip &&
    menuItems.push(
      <button key="del-equip" className="dropdown-item" onClick={onDelete} type="button">
        Удалить
      </button>,
    );

  return (
    <div className="d-flex justify-content-between align-items-center my-n1">
      <div className="d-flex flex-nowrap align-items-center ms-n2">
        <PohAva
          src={data.photo}
          alt={data.name}
          width={48}
          icon={<Sunglasses />}
          className="me-2"
          onClick={() => previewEquipModal(data)}
        />
        {!data.id_equip ? (
          <em className="text-muted" title="Ничейное">
            {data.name}
          </em>
        ) : (
          data.name
        )}
      </div>
      <aside className="d-flex flex-nowrap align-items-center">
        <EquipOptionsWidget weight={round(data.weight / 1000)} value={round(data.value / 1000)} />
        {!readonly && (
          <PohDropdown className="me-n2" menu={menuItems}>
            <PohButton icon={IconsEnum.right_menu} />
          </PohDropdown>
        )}
      </aside>
    </div>
  );
};

export default CommonEquipItem;
